"""Carrying an applied security fix into code generated again.

A fix reaches the code as a new code version, patched over the version it was
proposed against (`apply_proposal`). Generating again writes every file from
the design, so the next version used to lose every fix applied since without a
word: the regenerated file was the one the scan had flagged.

**Carried the way `git cherry-pick` carries a commit.** Each file the fix
changed is merged three ways: the file in the version the fix patched is the
base, the file the fix produced is ours, and the file just generated is
theirs. Where the generator wrote the lines around the fix as it wrote them
before, the fix lands as it was reviewed. The merge is git's own (`git
merge-file`), not one written here.

**All or nothing, as applying is.** A fix is carried only when every file it
changed merges cleanly. Otherwise every file stays as generated and the review
is told which fix did not carry and why. A file with conflict markers in it,
or a fix pushed into lines that are no longer the ones it was reviewed against,
would be unreviewed code in the one place where being wrong is worst.

**A fix is carried until a person lets it go.** Every generation tries every
applied fix again, so one that could not be carried into one version is tried
again in the next, whose design may have moved back. Approving a version the
fix was not carried into lets it go: the review said so, and the reviewer
decided the code without it is the code. Scanning that version is how the
weakness is found again if it is still there.

Known limits, said rather than hidden. The merge is line based, so a fix whose
lines merge cleanly into code whose meaning changed around them is carried,
and it is the build, the agreement check and the next scan that catch it. A
fix whose files span the frontend and the backend is not carried at all: the
two are generated by separate stages, and a fix carried into one of them only
would be half a fix.
"""

import asyncio
import os
import subprocess
import tempfile
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from sdlc_contracts import CodeRepository, ManifestRow, RemediationProposals

from .db import store
from .wording import stage_label

#: The program that merges. A name rather than a path, found the way a shell finds it.
GIT = "git"

#: Far longer than a merge of one generated file takes; a merge that has not
#: finished by then is not going to.
GIT_TIMEOUT_SECONDS = 30

#: Where a fix's file is filed when no manifest names its stage: an applied fix
#: files every file of its version under the backend stage.
UNNAMED_STAGE = "backend-code"


class MergeUnavailable(Exception):
    """git could not merge at all, as opposed to finding the two changes overlap."""


def merge_file(*, base: str, ours: str, theirs: str) -> str | None:
    """Merge one file three ways with `git merge-file`.

    The merged text, or None when the two changes touch the same lines. git
    exits with the number of conflicts (0 for a clean merge) and negatively on
    an error, which a process sees as 255; its own fatal errors exit 128.

    Neither the host's git configuration nor any repository around the
    temporary folder is read, so the same three files merge the same way
    wherever the orchestrator runs.
    """
    with tempfile.TemporaryDirectory(prefix="carry-") as folder:
        paths = []
        for name, text in (("ours", ours), ("base", base), ("theirs", theirs)):
            path = Path(folder) / name
            path.write_bytes(text.encode("utf-8"))
            paths.append(str(path))
        try:
            done = subprocess.run(
                [GIT, "merge-file", "-p", *paths],
                capture_output=True,
                timeout=GIT_TIMEOUT_SECONDS,
                cwd=folder,
                env={
                    **os.environ,
                    "GIT_CONFIG_NOSYSTEM": "1",
                    "GIT_CONFIG_GLOBAL": os.devnull,
                    "GIT_CEILING_DIRECTORIES": str(Path(folder).parent),
                },
                check=False,
            )
        except FileNotFoundError as missing:
            raise MergeUnavailable("git is not installed where the orchestrator runs") from missing
        except subprocess.TimeoutExpired as slow:
            raise MergeUnavailable(
                f"git did not finish merging within {GIT_TIMEOUT_SECONDS} seconds"
            ) from slow
        said = done.stderr.decode("utf-8", "replace").replace(f"{folder}/", "").strip()
    if done.returncode == 0:
        return done.stdout.decode("utf-8")
    if 0 < done.returncode < 128:
        return None
    if "binary" in said.lower():
        raise MergeUnavailable("it is not a text file, and git merges text")
    raise MergeUnavailable(f"git could not merge it ({said or f'exit {done.returncode}'})")


@dataclass(frozen=True)
class AppliedFix:
    """One applied fix, read from the decision its apply recorded and its proposal."""

    #: The code version the apply wrote, which is the fix's identity on the
    #: code axis: a proposal's id names a finding, and a later scan of the same
    #: finding proposes under the same id.
    version: int
    #: The code version it was applied over.
    patched: int
    proposal_id: str
    #: The test version it was proposed at, where its proposal is stored.
    test_version: int
    cwe: str
    #: The files its patch changed. Empty when its proposal cannot be read.
    paths: tuple[str, ...]

    def named(self) -> str:
        return f"the {self.cwe or 'security'} fix applied as code version {self.version}"


@dataclass
class Carrying:
    """What carrying the applied fixes made of one stage's files."""

    files: dict[str, str]
    manifest: list[ManifestRow]
    carried: list[AppliedFix] = field(default_factory=list)
    #: Each fix this stage did not carry, with why, in words a reviewer can act on.
    not_carried: list[tuple[AppliedFix, str]] = field(default_factory=list)


async def applied_fixes(conn: Any, project_id: str) -> list[AppliedFix]:
    """Every applied fix, oldest first, with the files its patch changed."""
    fixes = []
    for row in await store.applied_fixes(conn, project_id):
        found = await store.artefacts_at(
            conn, project_id, version=row["test_version"], kinds=("remediation-proposal",)
        )
        proposal = None
        if "remediation-proposal" in found:
            proposals = RemediationProposals.model_validate(found["remediation-proposal"]["body"])
            proposal = next(
                (one for one in proposals.proposals if one.id == row["proposal_id"]), None
            )
        fixes.append(
            AppliedFix(
                version=row["applied"],
                patched=row["patched"],
                proposal_id=row["proposal_id"],
                test_version=row["test_version"],
                cwe=proposal.cwe if proposal else "",
                paths=tuple(dict.fromkeys(hunk.path for hunk in proposal.patch))
                if proposal
                else (),
            )
        )
    return fixes


async def fixes_to_carry(conn: Any, project_id: str, *, version: int) -> list[AppliedFix]:
    """The applied fixes code generated at `version` carries, oldest first.

    Every fix applied before it, except one a person let go: one that a version
    generated after it was approved without.
    """
    fixes = [fix for fix in await applied_fixes(conn, project_id) if fix.version < version]
    if not fixes:
        return []
    written_by_a_fix = await store.patch_provenance(conn, project_id)
    approved: dict[int, set[int]] = {}
    for earlier in range(min(fix.version for fix in fixes) + 1, version):
        if earlier in written_by_a_fix or not await store.version_is_approved(
            conn, project_id, gate_kind="c2-code-review", version=earlier
        ):
            continue
        found = await store.artefacts_at(
            conn, project_id, version=earlier, kinds=("code-repository",)
        )
        if "code-repository" in found:
            manifest = CodeRepository.model_validate(found["code-repository"]["body"]).manifest
            approved[earlier] = {fixed for row in manifest for fixed in row.carried_fixes}
    return [
        fix
        for fix in fixes
        if not any(
            fix.version not in carried
            for earlier, carried in approved.items()
            if earlier > fix.version
        )
    ]


async def _stages_at(conn: Any, project_id: str, version: int) -> dict[str, str]:
    """Which stage wrote each file at a version, as its manifest says."""
    found = await store.artefacts_at(conn, project_id, version=version, kinds=("code-repository",))
    if "code-repository" not in found:
        return {}
    manifest = CodeRepository.model_validate(found["code-repository"]["body"]).manifest
    return {row.path: row.stage for row in manifest}


async def carry_fixes(
    conn: Any,
    project_id: str,
    *,
    stage_id: str,
    version: int,
    files: dict[str, str],
    manifest: list[ManifestRow],
) -> Carrying:
    """Carry into one stage's newly generated files every fix they should keep.

    A fix belongs to the stage that writes its first file: the stage that
    generated that file this time, or else the one that wrote it in the version
    the fix patched. So each fix is tried, and reported, by one stage, and a
    stage retried on its own carries its fixes again.
    """
    carrying = Carrying(files=dict(files), manifest=list(manifest))
    for fix in await fixes_to_carry(conn, project_id, version=version):
        if not fix.paths:
            # Reported once, by the stage an applied fix files its version under.
            if stage_id == UNNAMED_STAGE:
                carrying.not_carried.append(
                    (
                        fix,
                        f"its proposal could not be read at test version {fix.test_version}, "
                        "so which files it changed is not known",
                    )
                )
            continue
        before = await _stages_at(conn, project_id, fix.patched)
        first = fix.paths[0]
        if (stage_id if first in carrying.files else before.get(first, UNNAMED_STAGE)) != stage_id:
            continue
        reason = await _carry_one(conn, project_id, fix, carrying, stage_id=stage_id, before=before)
        if reason is None:
            carrying.carried.append(fix)
        else:
            carrying.not_carried.append((fix, reason))
    return carrying


async def _carry_one(
    conn: Any,
    project_id: str,
    fix: AppliedFix,
    carrying: Carrying,
    *,
    stage_id: str,
    before: dict[str, str],
) -> str | None:
    """Merge one fix into every file it changed, or into none.

    None when it was carried, otherwise why it was not.
    """
    merged: dict[str, str] = {}
    for path in fix.paths:
        if path not in carrying.files:
            other = before.get(path, UNNAMED_STAGE)
            if other == stage_id:
                return f"the code generated this time has no {path}"
            return (
                f"it also changes {path}, which the {stage_label(other)} stage writes, and a fix "
                "carried into one stage's files only would be half a fix"
            )
        base = await store.code_file(conn, project_id, version=fix.patched, path=path)
        ours = await store.code_file(conn, project_id, version=fix.version, path=path)
        if base is None or ours is None:
            missing = fix.patched if base is None else fix.version
            return f"{path} is missing from code version {missing}, so there is nothing to merge"
        try:
            result = await asyncio.to_thread(
                merge_file, base=base, ours=ours, theirs=carrying.files[path]
            )
        except MergeUnavailable as error:
            return f"{path} could not be merged: {error}"
        if result is None:
            return (
                f"the code generated this time changed the lines of {path} that the fix "
                "changed, so the two cannot both be kept"
            )
        merged[path] = result
    carrying.files.update(merged)
    carrying.manifest = [
        row.model_copy(update={"carried_fixes": [*row.carried_fixes, fix.version]})
        if row.path in merged
        else row
        for row in carrying.manifest
    ]
    return None
